// Neon spectrum is decorative wild artwork; ordinary trait colors stay in dgn-traits.js.
export const DGN_WILD_SPECTRUM = Object.freeze([
  '#ff08d1', '#902bff', '#2354ff', '#00d9ff',
  '#00f5a1', '#b5ff00', '#ffe12b', '#ff602e',
]);

function toHsl(hex) {
  const [r, g, b] = [1, 3, 5].map(offset => parseInt(hex.slice(offset, offset + 2), 16) / 255);
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  const delta = max - min, lightness = (max + min) / 2;
  const hue = !delta ? 0 : max === r ? ((g - b) / delta + 6) % 6
    : max === g ? (b - r) / delta + 2 : (r - g) / delta + 4;
  return [hue * 60, delta ? delta / (1 - Math.abs(2 * lightness - 1)) : 0, lightness];
}

const hsl = new Map(DGN_WILD_SPECTRUM.map(color => [color, toHsl(color)]));

/** Short-hue interpolation keeps the spectrum saturated between color stops. */
export function sampleWildSpectrum(colors, position) {
  const index = Math.floor(position) % colors.length;
  const mix = position - Math.floor(position);
  const from = colors[index], to = colors[(index + 1) % colors.length];
  if (!mix) return from;
  const a = hsl.get(from), b = hsl.get(to);
  const hue = (a[0] + (((b[0] - a[0] + 540) % 360) - 180) * mix + 360) % 360;
  const saturation = a[1] + (b[1] - a[1]) * mix;
  const lightness = a[2] + (b[2] - a[2]) * mix;
  const chroma = (1 - Math.abs(2 * lightness - 1)) * saturation;
  const x = chroma * (1 - Math.abs((hue / 60) % 2 - 1));
  const m = lightness - chroma / 2;
  const rgb = [[chroma, x, 0], [x, chroma, 0], [0, chroma, x],
    [0, x, chroma], [x, 0, chroma], [chroma, 0, x]][Math.floor(hue / 60)];
  return '#' + rgb.map(value => Math.round((value + m) * 255).toString(16).padStart(2, '0')).join('');
}

/** Dense shared stops keep CSS and SVG/canvas reveals on the same spectrum. */
export function wildSpectrumGradient(colors) {
  const steps = colors.length * 8;
  const stops = Array.from({ length: steps + 1 }, (_, i) => `${sampleWildSpectrum(colors, i / 8)} ${i * 360 / steps}deg`);
  return `conic-gradient(from -22.5deg, ${stops.join(', ')})`;
}
